import math


class CrossEncoderReranker:
    def __init__(self, corpus):
        self.corpus = corpus

    @staticmethod
    def _tokens(text):
        return text.lower().split()

    def bi_encoder_score(self, query, doc):
        q = set(self._tokens(query))
        d = set(self._tokens(doc))
        if not q or not d:
            return 0.0
        return len(q & d) / math.sqrt(len(q) * len(d))

    def cross_encoder_score(self, query, doc):
        q = self._tokens(query)
        d = self._tokens(doc)
        if not q or not d:
            return 0.0
        dset = set(d)
        coverage = sum(1 for t in q if t in dset) / len(q)
        q_bi = set(zip(q, q[1:]))
        d_bi = set(zip(d, d[1:]))
        bigram = len(q_bi & d_bi) / len(q_bi) if q_bi else 0.0
        return coverage + 0.5 * bigram + 0.1 * self.bi_encoder_score(query, doc)

    def retrieve_and_rerank(self, query, top_k=5, rerank_pool=10):
        scored = sorted(
            range(len(self.corpus)),
            key=lambda i: (-self.bi_encoder_score(query, self.corpus[i]), i),
        )[:rerank_pool]
        reranked = sorted(
            scored,
            key=lambda i: (-self.cross_encoder_score(query, self.corpus[i]), i),
        )[:top_k]
        return [(self.corpus[i], self.cross_encoder_score(query, self.corpus[i])) for i in reranked]


class RerankerBenchmark:
    def __init__(self, corpus: list[str]):
        self.reranker = CrossEncoderReranker(corpus)
        self.corpus = corpus

    def reciprocal_rank(self, ranked_docs: list[str], relevant: set[str]) -> float:
        """Return 1/rank of the first relevant doc, or 0.0 if none found"""
        for rank, doc in enumerate(ranked_docs, start=1):
            if doc in relevant:
                return 1.0 / rank
        return 0.0

    def evaluate(self, queries: list[str], ground_truth: list[set[int]], top_k: int = 5) -> dict:
        bi_rrs = []
        rr_rrs = []
        for query, rel_idx in zip(queries, ground_truth):
            relevant = {self.corpus[i] for i in rel_idx if 0 <= i < len(self.corpus)}
            order = sorted(
                range(len(self.corpus)),
                key=lambda i: (-self.reranker.bi_encoder_score(query, self.corpus[i]), i),
            )[:top_k]
            bi_docs = [self.corpus[i] for i in order]
            reranked = self.reranker.retrieve_and_rerank(query, top_k, rerank_pool=top_k)
            rr_docs = [doc for doc, _ in reranked]
            bi_rrs.append(self.reciprocal_rank(bi_docs, relevant))
            rr_rrs.append(self.reciprocal_rank(rr_docs, relevant))
        n = len(queries) or 1
        mrr_bi = sum(bi_rrs) / n
        mrr_rr = sum(rr_rrs) / n
        return {
            "mrr_bi_encoder": mrr_bi,
            "mrr_reranked": mrr_rr,
            "improvement": mrr_rr - mrr_bi,
        }


corpus = [
    "python web framework flask tutorial",
    "javascript react frontend development",
    "python django rest api backend",
    "cooking italian pasta recipes",
    "python fastapi modern web development",
]

bench = RerankerBenchmark(corpus)
result = bench.evaluate(
    queries=["python web development", "frontend javascript"],
    ground_truth=[{0, 2, 4}, {1}],
    top_k=5,
)
print(f"Bi-encoder MRR: {result['mrr_bi_encoder']:.2f}")
print(f"Reranked MRR:   {result['mrr_reranked']:.2f}")
print(f"Improvement:    {result['improvement']:.2f}")
print(result["mrr_reranked"] >= result["mrr_bi_encoder"])
